class MobDocUnplannedCount extends TFMDocumentHandler
{
    InventDim               inventDim;
    InventTable             inventTable;
    inventJournalTable      inventJournalTable;
    InventJournalTrans      inventJournalTrans;
    TFMInventDimSetup       mobInventDimSetup;
